# Review package: 4adb16b..HEAD

## Commits
3521e49 test: assert topWords prefix and clarify wordCount test name

## Files changed
 test/topWords.test.js  | 6 +++++-
 test/wordCount.test.js | 2 +-
 2 files changed, 6 insertions(+), 2 deletions(-)

## Diff
diff --git a/test/topWords.test.js b/test/topWords.test.js
index 49144ca..e9699c2 100644
--- a/test/topWords.test.js
+++ b/test/topWords.test.js
@@ -88,21 +88,25 @@ test('throws a RangeError naming the function for an invalid n', () => {
   for (const bad of [undefined, NaN, '3', 1.5, -1, Infinity, null]) {
     assert.throws(() => topWords('apple', bad), (err) => {
       assert.ok(err instanceof RangeError);
       assert.ok(err.message.startsWith('topWords:'));
       return true;
     });
   }
 });

 test('checks the text before n', () => {
-  assert.throws(() => topWords(5, -1), TypeError);
+  assert.throws(() => topWords(5, -1), (err) => {
+    assert.ok(err instanceof TypeError);
+    assert.ok(err.message.startsWith('topWords:'));
+    return true;
+  });
 });

 test('folds case and typographic apostrophes into one entry', () => {
   assert.deepEqual(topWords("Éclair éclair ÉCLAIR keeper’s keeper's", 5), [
     { word: 'éclair', count: 3 },
     { word: "keeper's", count: 2 },
   ]);
 });

 test('returns fresh objects that callers may mutate', () => {
diff --git a/test/wordCount.test.js b/test/wordCount.test.js
index 142eee1..04dc2dc 100644
--- a/test/wordCount.test.js
+++ b/test/wordCount.test.js
@@ -95,21 +95,21 @@ test('drops a stray trailing hyphen or apostrophe from a word', () => {
   assert.equal(wordCount("dogs'"), 1);
   assert.equal(wordCount('dogs’'), 1);
   assert.equal(wordCount("the dogs' bowls"), 3);
 });

 test('drops a stray leading hyphen or apostrophe from a word', () => {
   assert.equal(wordCount('-well'), 1);
   assert.equal(wordCount("'tis"), 1);
 });

-test('does not count a lone hyphen or quote marks as words', () => {
+test('does not count a lone hyphen or surrounding quote marks as words', () => {
   assert.equal(wordCount('a - b'), 2);
   assert.equal(wordCount("'quoted'"), 1);
 });

 test('does not join across doubled joiners', () => {
   assert.equal(wordCount('well--known'), 2);
   assert.equal(wordCount("don''t"), 2);
   assert.equal(wordCount("a-'b"), 2);
 });

